service_evidence AS (
  SELECT DISTINCT address, name AS service_name, lower(trim(category)) AS service_category,
    concat('labels.addresses; model=', coalesce(model_name, ''), '; source=', coalesce(source, '')) AS evidence_source,
    concat('identifier=', name, '; label updated=', coalesce(cast(updated_at AS varchar), '')) AS evidence_detail
  FROM labels.addresses
  WHERE blockchain = 'ethereum'
    AND lower(trim(label_type)) = 'identifier'
    AND lower(trim(category)) IN ('cex', 'dex', 'lending', 'aggregator', 'bridge', 'mixer')
    AND nullif(trim(name), '') IS NOT NULL
    AND (nullif(trim(source), '') IS NOT NULL OR nullif(trim(model_name), '') IS NOT NULL)
  UNION ALL
  SELECT address, service_name, 'reviewed_function', evidence_source, evidence_detail FROM reviewed_services
),
service_addresses AS (SELECT DISTINCT address FROM service_evidence),
raw_relevant_eth_transfers AS (
  SELECT
    t.block_number, t.hash AS tx_hash,
    t."from" AS address_from, t."to" AS address_to
  FROM ethereum.transactions AS t
  WHERE t.block_number BETWEEN 10000835 AND 15400000
    AND t.success = true
    AND t.value > 0
    AND t."from" <> t."to"
    AND t."to" IS NOT NULL
    AND (
      t."from" IN (SELECT address FROM requested_addresses)
      OR t."to" IN (SELECT address FROM requested_addresses)
    )
),
relevant_eth_transfers AS (
  SELECT t.* FROM raw_relevant_eth_transfers t
  WHERE NOT EXISTS (
    SELECT 1 FROM service_addresses s
    WHERE s.address = t.address_from OR s.address = t.address_to
  )
),
touched_service_evidence AS (
  SELECT DISTINCT s.* FROM service_evidence s
  WHERE s.address IN (SELECT address_from FROM raw_relevant_eth_transfers
                      UNION SELECT address_to FROM raw_relevant_eth_transfers)
),
service_audit AS (
  SELECT coalesce(json_format(cast(array_agg(map(
    ARRAY['address','service_name','service_category','evidence_source','evidence_detail'],
    ARRAY[lower(concat('0x',to_hex(address))),service_name,service_category,evidence_source,evidence_detail]
  )) AS JSON)), '[]') AS evidence_json
  FROM touched_service_evidence
),
oriented_neighbor_summaries AS (
  SELECT
    address_from AS endpoint, address_to AS neighbor,
    count(*) AS transfer_count,
    min(block_number) AS first_block,
    max(block_number) AS last_block,
    min_by(tx_hash, block_number) AS example_tx_hash
  FROM relevant_eth_transfers
  WHERE address_from IN (SELECT address FROM requested_addresses)
  GROUP BY 1, 2
  UNION ALL
  SELECT
    address_to AS endpoint, address_from AS neighbor,
    count(*) AS transfer_count,
    min(block_number) AS first_block,
    max(block_number) AS last_block,
    min_by(tx_hash, block_number) AS example_tx_hash
  FROM relevant_eth_transfers
  WHERE address_to IN (SELECT address FROM requested_addresses)
  GROUP BY 1, 2
),
undirected_neighbors AS (
  SELECT
    endpoint, neighbor, sum(transfer_count) AS transfer_count,
    min(first_block) AS first_block, max(last_block) AS last_block,
    min_by(example_tx_hash, first_block) AS example_tx_hash
  FROM oriented_neighbor_summaries
  GROUP BY 1, 2
),
direct_evidence AS (
  SELECT p.pair_id, n.transfer_count, n.first_block, n.last_block,
         n.example_tx_hash
  FROM requested_pairs AS p
  JOIN undirected_neighbors AS n
    ON n.endpoint = p.address_a AND n.neighbor = p.address_b
),
two_hop_paths AS (
  SELECT
    p.pair_id, a.neighbor AS intermediary,
    least(a.first_block, b.first_block) AS first_block,
    greatest(a.last_block, b.last_block) AS last_block,
    a.example_tx_hash AS example_tx_hash_a,
    b.example_tx_hash AS example_tx_hash_b
  FROM requested_pairs AS p
  JOIN undirected_neighbors AS a ON a.endpoint = p.address_a
  JOIN undirected_neighbors AS b
    ON b.endpoint = p.address_b AND b.neighbor = a.neighbor
  WHERE a.neighbor <> p.address_a
    AND a.neighbor <> p.address_b
),
two_hop_evidence AS (
  SELECT
    pair_id, count(*) AS intermediary_count,
    min(first_block) AS first_block, max(last_block) AS last_block,
    min_by(intermediary, intermediary) AS example_intermediary,
    min_by(example_tx_hash_a, intermediary) AS example_tx_hash_a,
    min_by(example_tx_hash_b, intermediary) AS example_tx_hash_b
  FROM two_hop_paths
  GROUP BY 1
)
SELECT
  p.pair_id,
  lower(concat('0x', to_hex(p.address_a))) AS address_a,
  lower(concat('0x', to_hex(p.address_b))) AS address_b,
  coalesce(d.transfer_count, 0) AS direct_transfer_count,
  d.first_block AS direct_first_block,
  d.last_block AS direct_last_block,
  CASE WHEN d.example_tx_hash IS NULL THEN NULL
       ELSE lower(concat('0x', to_hex(d.example_tx_hash))) END
       AS direct_example_tx_hash,
  coalesce(h.intermediary_count, 0) AS two_hop_intermediary_count,
  h.first_block AS two_hop_first_block,
  h.last_block AS two_hop_last_block,
  CASE WHEN h.example_intermediary IS NULL THEN NULL
       ELSE lower(concat('0x', to_hex(h.example_intermediary))) END
       AS two_hop_example_intermediary,
  CASE WHEN h.example_tx_hash_a IS NULL THEN NULL
       ELSE lower(concat('0x', to_hex(h.example_tx_hash_a))) END
       AS two_hop_example_tx_hash_a,
  CASE WHEN h.example_tx_hash_b IS NULL THEN NULL
       ELSE lower(concat('0x', to_hex(h.example_tx_hash_b))) END
       AS two_hop_example_tx_hash_b,
  CASE WHEN d.pair_id IS NOT NULL THEN 1
       WHEN h.pair_id IS NOT NULL THEN 2 ELSE NULL END
       AS shortest_path_hops,
  (d.pair_id IS NOT NULL OR h.pair_id IS NOT NULL)
       AS entity_relationship_found,
  CASE WHEN p.pair_id = (SELECT min(pair_id) FROM requested_pairs)
       THEN (SELECT evidence_json FROM service_audit) ELSE NULL END AS service_evidence_json
FROM requested_pairs AS p
LEFT JOIN direct_evidence AS d ON d.pair_id = p.pair_id
LEFT JOIN two_hop_evidence AS h ON h.pair_id = p.pair_id
ORDER BY p.pair_id

